@patch
def status(self: Kosha, pyproject=True, depth=1) -> dict:
	'Index freshness: file/pkg/node counts and stale file count.'
	known = {r['path']: r['uploaded_at'] for r in self.code_st(select='path,uploaded_at') if r['path']}
	stale = sum(1 for p, mt in known.items() if Path(p).exists() and Path(p).stat().st_mtime != mt)
	new = sum(1 for p in dir2files(self.root,strict_skip_file_re,repo_skip_folder_re,exts=['.py']) if str(p) not in known)
	pkgs={r['name']: r['version'] for r in self.pkgs_in_env(pyproject, depth)}
	sp = filter_keys(env_pkg_versions(pyproject,depth),not_(in_(pkgs)))
	return dict(files=len(known), packages=self.pkgs.count, graph_nodes=self.gn.count, stale_files=stale, stale_pkgs=sp, new_files=new)

# %% ../nbs/01_graph.ipynb #rank_helpers_a1
# Symbol-lookup queries: namespace-qualified, leading-underscore, or containing uppercase/underscore.
_SYMBOL_QUERY_RE = re.compile(
    r"^(?:"
    r"[A-Za-z_][A-Za-z0-9_]*(?:(?:::|\\|->|\.)[A-Za-z_][A-Za-z0-9_]*)+"  # namespace-qualified
    r"|_[A-Za-z0-9_]*"  # leading underscore
    r"|[A-Za-z][A-Za-z0-9]*[A-Z_][A-Za-z0-9_]*"  # contains uppercase or underscore
    r"|[A-Z][A-Za-z0-9]*"  # starts with uppercase
    r")$")
# CamelCase/camelCase identifiers embedded in an NL query.
_EMBEDDED_SYMBOL_RE = re.compile(
    r"\b(?:"
    r"[A-Z][a-z][a-zA-Z0-9]*[A-Z][a-zA-Z0-9]*"  # PascalCase
    r"|[a-z][a-zA-Z0-9]*[A-Z][a-zA-Z0-9]+"  # camelCase
    r")\b")
_CAMEL_RE = re.compile(r"[A-Z]+(?=[A-Z][a-z])|[A-Z]?[a-z]+|[A-Z]+|[0-9]+")

_EMBEDDED_SYMBOL_BOOST_SCALE = 0.5  # embedded symbol may be incidental to the NL query
_DEFINITION_KEYWORDS = ("class","module","defmodule","def","interface","struct","enum","trait","type","func",
    "function","object","abstract class","data class","fn","fun","package","namespace","protocol","record","typedef")
_SQL_DEFINITION_KEYWORDS = ("CREATE TABLE","CREATE VIEW","CREATE PROCEDURE","CREATE FUNCTION")
_KEYWORD_PREFIX = r"(?:^|(?<=\s))(?:"
_DEFINITION_KEYWORD_BODY = "|".join(re.escape(k) for k in _DEFINITION_KEYWORDS)
_SQL_KEYWORD_BODY = "|".join(re.escape(k) for k in _SQL_DEFINITION_KEYWORDS)
_DEFINITION_BOOST_MULTIPLIER = 3.0  # additive boost for chunks defining a queried symbol
_STEM_BOOST_MULTIPLIER = 1.0        # additive boost for NL queries when file stems match query words
_FILE_COHERENCE_BOOST_FRAC = 0.2    # fraction of max_score added to a file's top chunk, scaled by aggregate score
_STOPWORDS = frozenset(
    "a an and are as at be by do does for from has have how if in is it not of on or the to was"
    " what when where which who why with".split())

_PACKAGE_BOOST = 1.5  # multiplicative boost for chunks in a soft-requested package

_TEST_FILE_RE = re.compile(
    r"(?:^|/)(?:"
    r"test_[^/]*\.py|[^/]*_test\.py|[^/]*_test\.go|[^/]*Tests?\.java|[^/]*Test\.php|[^/]*_spec\.rb|[^/]*_test\.rb"
    r"|[^/]*\.test\.[jt]sx?|[^/]*\.spec\.[jt]sx?|[^/]*Tests?\.kt|[^/]*Spec\.kt|[^/]*Tests?\.swift|[^/]*Spec\.swift"
    r"|[^/]*Tests?\.cs|test_[^/]*\.cpp|[^/]*_test\.cpp|test_[^/]*\.c|[^/]*_test\.c|[^/]*Spec\.scala|[^/]*Suite\.scala"
    r"|[^/]*Test\.scala|[^/]*_test\.dart|test_[^/]*\.dart|[^/]*_spec\.lua|[^/]*_test\.lua|test_[^/]*\.lua"
    r"|test_helpers?[^/]*\.\w+)$")
_TEST_DIR_RE = re.compile(r"(?:^|/)(?:tests?|__tests__|spec|testing)(?:/|$)")
_COMPAT_DIR_RE = re.compile(r"(?:^|/)(?:compat|_compat|legacy)(?:/|$)")
_EXAMPLES_DIR_RE = re.compile(r"(?:^|/)(?:_?examples?|docs?_src)(?:/|$)")
_TYPE_DEFS_RE = re.compile(r"\.d\.ts$")
_STRONG_PENALTY, _MODERATE_PENALTY, _MILD_PENALTY = 0.3, 0.5, 0.7
_REEXPORT_FILENAMES = frozenset({"__init__.py", "package-info.java"})
_FILE_SATURATION_THRESHOLD, _FILE_SATURATION_DECAY = 1, 0.5

def is_symbol_query(query:str) -> bool:
    'True if the query looks like a bare symbol or namespace-qualified identifier.'
    return _SYMBOL_QUERY_RE.match(query.strip()) is not None

def _split_ident(token:str) -> list:
    'Split an identifier into sub-tokens via camelCase/snake_case (lowered); keeps the whole token.'
    lower = token.lower()
    parts = [p for p in lower.split('_') if p] if '_' in token else [m.lower() for m in _CAMEL_RE.findall(token)]
    return [lower, *parts] if len(parts) >= 2 else [lower]

# ── result-dict accessors ──
def _rk_score(r): return float(r.get('_rrf_score') or r.get('_score') or 0.0)
def _rk_fpath(r): return r.get('path') or (r.get('metadata') or {}).get('path') or ''
def _rk_content(r): return r.get('content') or ''
def _rk_pkg(r): return r.get('package') or (r.get('metadata') or {}).get('package')
def _extract_symbol_name(query:str) -> str:
    'Final identifier of a possibly namespace-qualified query ("Sinatra::Base" -> "Base").'
    for sep in ('::', '\\', '->', '.'):
        if sep in query: return query.rsplit(sep, 1)[-1]
    return query.strip()

@functools.lru_cache(maxsize=256)
def _definition_pattern(symbol_name:str):
    escaped, ns_prefix = re.escape(symbol_name), r"(?:[A-Za-z_][A-Za-z0-9_]*(?:\.|::))*"
    suffix = r")\s+" + ns_prefix + escaped + r"(?:\s|[<({:\[;]|$)"
    return (re.compile(_KEYWORD_PREFIX + _DEFINITION_KEYWORD_BODY + suffix, re.MULTILINE),
            re.compile(_KEYWORD_PREFIX + _SQL_KEYWORD_BODY + suffix, re.MULTILINE | re.IGNORECASE))

def _defines_symbol(content:str, name:str) -> bool:
    general, sql = _definition_pattern(name)
    return general.search(content) is not None or sql.search(content) is not None

def _stem_matches(stem:str, name:str) -> bool:
    'True if stem matches name (exact, snake_case-normalised, or plural).'
    sn = stem.replace('_', '')
    return stem == name or sn == name or stem.rstrip('s') == name or sn.rstrip('s') == name

def _definition_tier(content:str, fpath:str, names:set, boost_unit:float) -> float:
    'Boost amount for a chunk defining one of names (0.0 if none), 1.5x when the file stem also matches.'
    if not any(_defines_symbol(content, n) for n in names): return 0.0
    stem = Path(fpath).stem.lower()
    return boost_unit * (1.5 if any(_stem_matches(stem, n.lower()) for n in names) else 1.0)

def _count_keyword_matches(keywords:set, parts:set) -> int:
    'Count query keywords matching path parts, allowing prefix overlap (min 3 chars).'
    exact = keywords & parts
    if len(exact) == len(keywords): return len(exact)
    n = len(exact)
    for kw in keywords - exact:
        for part in parts:
            shorter, longer = (kw, part) if len(kw) <= len(part) else (part, kw)
            if len(shorter) >= 3 and longer.startswith(shorter): n += 1; break
    return n

def _boost_symbol_defs(results, scores, query, mx):
    sym = _extract_symbol_name(query); names = {sym}
    if sym != query.strip(): names.add(query.strip())
    bu = mx * _DEFINITION_BOOST_MULTIPLIER
    for i, r in enumerate(results):
        if t := _definition_tier(_rk_content(r), _rk_fpath(r), names, bu): scores[i] += t

def _boost_embedded(results, scores, query, mx):
    names = set(_EMBEDDED_SYMBOL_RE.findall(query))
    if not names: return
    bu = mx * _DEFINITION_BOOST_MULTIPLIER * _EMBEDDED_SYMBOL_BOOST_SCALE
    for i, r in enumerate(results):
        if t := _definition_tier(_rk_content(r), _rk_fpath(r), names, bu): scores[i] += t

def _boost_stems(results, scores, query, mx):
    keywords = {w.lower() for w in re.findall(r"[a-zA-Z_][a-zA-Z0-9_]*", query)
                if len(w) > 2 and w.lower() not in _STOPWORDS}
    if not keywords: return
    boost = mx * _STEM_BOOST_MULTIPLIER
    for i, r in enumerate(results):
        path = Path(_rk_fpath(r)); parts = set(_split_ident(path.stem))
        if path.parent.name and path.parent.name not in ('.', '/', '..'): parts |= set(_split_ident(path.parent.name))
        n = _count_keyword_matches(keywords, parts)
        if n and (ratio := n / len(keywords)) >= 0.10: scores[i] += boost * ratio

def _apply_query_boost(results, scores, query):
    'Query-type boosts over the candidate pool (in-place): symbol-definition, or NL stem + embedded-symbol.'
    if not scores: return
    mx = max(scores)
    if is_symbol_query(query): _boost_symbol_defs(results, scores, query, mx)
    else: _boost_stems(results, scores, query, mx); _boost_embedded(results, scores, query, mx)

def _boost_multi_chunk(results, scores):
    'Promote files with multiple high-scoring chunks by boosting their top chunk (in-place).'
    if not scores or (mx := max(scores)) == 0.0: return
    fsum, best = {}, {}
    for i, r in enumerate(results):
        fp = _rk_fpath(r); fsum[fp] = fsum.get(fp, 0.0) + scores[i]
        if fp not in best or scores[i] > scores[best[fp]]: best[fp] = i
    mfs, unit = max(fsum.values()), mx * _FILE_COHERENCE_BOOST_FRAC
    for fp, i in best.items(): scores[i] += unit * fsum[fp] / mfs

def _boost_package(results, scores, soft_pkgs):
    'Multiplicatively boost chunks whose package is soft-requested (in-place). Non-filtering.'
    if not soft_pkgs: return
    sp = {p.lower() for p in soft_pkgs}
    for i, r in enumerate(results):
        if (pk := _rk_pkg(r)) and pk.lower() in sp: scores[i] *= _PACKAGE_BOOST

def _file_penalty(fpath:str) -> float:
    'Combined multiplicative penalty for test/compat/example/re-export/.d.ts paths.'
    norm = fpath.replace('\\', '/'); penalty = 1.0
    if _TEST_FILE_RE.search(norm) or _TEST_DIR_RE.search(norm): penalty *= _STRONG_PENALTY
    if Path(fpath).name in _REEXPORT_FILENAMES: penalty *= _MODERATE_PENALTY
    if _COMPAT_DIR_RE.search(norm): penalty *= _STRONG_PENALTY
    if _EXAMPLES_DIR_RE.search(norm): penalty *= _STRONG_PENALTY
    if _TYPE_DEFS_RE.search(norm): penalty *= _MILD_PENALTY
    return penalty

def _rerank_topk(results, scores, top_k, penalise_paths=True):
    'Top-k indices with path penalties + file-saturation decay. Returns [(idx, score)] highest first.'
    n = len(results)
    if n == 0: return []
    cache, pen = {}, [0.0]*n
    for i, r in enumerate(results):
        if penalise_paths:
            fp = _rk_fpath(r)
            if fp not in cache: cache[fp] = _file_penalty(fp)
            pen[i] = scores[i] * cache[fp]
        else: pen[i] = scores[i]
    ranked = sorted(range(n), key=lambda i: -pen[i])
    fsel, selected, min_sel = {}, [], float('inf')
    for i in ranked:
        ps = pen[i]
        if len(selected) >= top_k and ps <= min_sel: break
        already = fsel.get(_rk_fpath(results[i]), 0); eff = ps
        if already >= _FILE_SATURATION_THRESHOLD:
            eff *= _FILE_SATURATION_DECAY ** (already - _FILE_SATURATION_THRESHOLD + 1)
        selected.append((eff, i)); fsel[_rk_fpath(results[i])] = already + 1
        if len(selected) >= top_k: min_sel = min(s for s, _ in selected)
    selected.sort(key=lambda t: -t[0])
    return [(i, s) for s, i in selected[:top_k]]

def rank_results(results, query, soft_pkgs=None, top_k=None, penalise_paths=True) -> L:
    'Rerank result dicts: query boosts + soft-package boost + semble-style path penalties.'
    results = list(results)
    if not results or not (query and query.strip()): return L(results)[:top_k] if top_k else L(results)
    scores = [_rk_score(r) for r in results]
    if max(scores, default=0.0) == 0.0: scores = [1.0/(i+1) for i in range(len(results))]  # keep incoming order
    _apply_query_boost(results, scores, query)
    _boost_package(results, scores, soft_pkgs)
    _boost_multi_chunk(results, scores)
    ranked = _rerank_topk(results, scores, top_k or len(results), penalise_paths)
    return L(results[i] | {'_score': s} for i, s in ranked)

