import hashlib

# %% ../nbs/01_graph.ipynb #9035c5d9
def _source_hash(src): return hashlib.blake2b(src.encode(), digest_size=16).hexdigest()
def _by_root(files, root=None):
	'{root: [files]} — one group when `root` is given, else grouped by import root.'
	if root: return {Path(root): list(files)}
	out = {}
	for f in files: out.setdefault(imp_root(f), []).append(f)
	return out

@patch
def _drop_file(self: CodeGraph, path: str, incoming=True):
    'Delete graph rows generated by one source file.'
    nodes = self.file2nodes(path)
    if nodes:
        pl = ','.join('?' * len(nodes)); args = list(nodes)
        where = f'caller IN ({pl})' + (f' OR callee IN ({pl})' if incoming else '')
        self.db.q(f'DELETE FROM graph_edges WHERE {where}', args * (2 if incoming else 1))
        self.db.q(f'DELETE FROM graph_nodes WHERE node IN ({pl})', args)
        self.db.q(f'DELETE FROM pending_attr_calls WHERE caller IN ({pl})', args)
        self.db.q(f'DELETE FROM co_dispatch WHERE node IN ({pl})', args)
    self.db.q('DELETE FROM file_index WHERE path=?', [path])

@patch
def _index_files(self: CodeGraph, files, sc='repo'):
    rows = []
    for f in files:
        p = Path(f); src = p.read_text(errors='replace')
        rows.append({'path': str(p), 'root': sc, 'source_hash': _source_hash(src), 'last_analyzed_at': p.stat().st_mtime})
    if rows: self.db.t.file_index.insert_all(rows, replace=True)

@patch
def _stale(self: CodeGraph, files, sc=None, force=False):
    kw = dict(where='root=?', where_args=[sc]) if sc else {}
    known = {r['path']: r.get('source_hash') for r in self.db.t.file_index(**kw)}
    out = []
    for f in files:
        p = Path(f)
        if not p.exists(): continue
        src = p.read_text(errors='replace')
        if force or known.get(str(p)) != _source_hash(src): out.append(f)
    return out

@patch
def _fast_process_files(self: CodeGraph, files, root=None, full=False):
	'Re-extract the changed files in one pass.'
	if not files: return self
	old = set().union(*(self.file2nodes(str(f)) for f in files))
	for f in files: self._drop_file(str(f), incoming=False)
	if full: self.process_files(files, root=root)
	else:
		groups = _by_root(files, root)
		self._write_batch([_static_batch(dict(filenames=[str(f) for f in fl], root=str(r)))
		                   for r, fl in groups.items()])
		self._add_dyn({'.'.join(Path(f).relative_to(r).with_suffix('').parts): Path(f)
		               for r, fl in groups.items() for f in fl})
		self.resolve_attr_calls()
	gone = old - set().union(*(self.file2nodes(str(f)) for f in files))
	if gone:
		pl = ','.join('?' * len(gone))
		self.db.q(f'DELETE FROM graph_edges WHERE callee IN ({pl})', list(gone))
	return self

@patch
def sync_dir(self: CodeGraph, dir: str | Path, force=False, mode='fast', root=None) -> 'CodeGraph':
    'Incremental directory sync; unchanged source hashes are skipped.'
    if not dir: return self
    files = dir2files(dir, exts=['.py'], func=os.path.join)
    known = set(L(self.db.t.file_index(select='distinct path', where='root=?', where_args=[str(dir)])).attrgot('path'))
    removed = known - set(files)
    for f in removed: self._drop_file(f)
    changed = self._stale(files, str(dir), force)
    if changed: self._fast_process_files(changed, str(root) if root else None, full=mode == 'full'); self._index_files(changed, str(dir))
    self._graph_changed = getattr(self, '_graph_changed', False) or bool(removed or changed)
    return self

@patch
def sync_pkgs(self: CodeGraph, pkgs: list[str], force=False, mode='fast') -> 'CodeGraph':
    'Incrementally sync installed packages by source hash.'
    for pkg in tqdm(pkgs or [], desc='loading code graph for packages', unit='pkg'):
        s = spec(pkg)
        if not s: continue
        p = Path(s.origin).parent if s.origin else Path(s.submodule_search_locations[0])
        self.sync_dir(p, force=force, mode=mode, root=p.parent)
    return self

@patch
def sync(self: CodeGraph, dir=None, pkgs=None, force=False, mode='fast', metrics=True) -> 'CodeGraph':
    'Incremental graph sync; mode="full" fans out over processes, metrics=False defers PageRank.'
    self._graph_changed = force
    if force: self.pa.delete_where()
    if dir: self.sync_dir(dir, force=force, mode=mode)
    if pkgs: self.sync_pkgs(pkgs, force=force, mode=mode)
    if metrics and self._graph_changed: self._centrality()
    return self

@patch
def recompute_metrics(self: CodeGraph) -> 'CodeGraph':
    'Recompute PageRank and degree metrics once after graph updates.'
    return self._centrality(force=True)

@patch
def resolve_attr_calls(self: CodeGraph) -> 'CodeGraph':
    'Resolve pending attribute calls using the indexed method column.'
    existing = {(r['caller'], r['callee']) for r in self.ge(select='caller,callee')}
    new_edges = []
    for r in self.pa():
        if not r['pkgs']: continue
        pkgs = {pkg: i for i, pkg in enumerate(r['pkgs'].split(','))}
        candidates = [x for x in self.gn(where='method=?', where_args=[r['method']]) if x['node'].split('.')[0] in pkgs]
        if not candidates: continue
        callee = max((x['node'] for x in candidates), key=lambda n: pkgs.get(n.split('.')[0], -1))
        if (r['caller'], callee) not in existing:
            new_edges.append(_e(r['caller'], callee, 'attr_call', 0.7)); existing.add((r['caller'], callee))
    if new_edges: self.ge.insert_all(new_edges, upsert=True, pk=('caller','callee','kind'))
    return self


